INSERT INTO `herinnering text` VALUES (1,'betalingsverzoek','Na controle van onze administratie zien wij dat bijgaande factuur/facturen nog niet is/zijn voldaan. Wellicht is dit aan uw aandacht ontsnapt.\r\n\r\nMocht er een reden zijn waarom u nog niet heeft betaald, laat het ons weten, anders zien wij graag de betaling tegemoet op bankrekeningnummer NL83RABO0318111128 t.n.v. Nieuwenhuizen Sprang-Capelle BV.\r\n\r\nWanneer u reeds heeft betaald, dan kunt u dit schrijven als niet verzonden beschouwen.'),(2,'2e betalingsverzoek','Na het betalingsverzoek welke wij u eerder toezonden, hebben wij helaas nog geen betaling van u mogen ontvangen. Hierbij verzoeken wij u het verschuldigde bedrag per omgaande over te maken op ons bankrekeningnummer NL83RABO0318111128 t.n.v. Nieuwenhuizen Sprang-Capelle BV.\r\n\r\nMocht er een reden zijn waarom het openstaande bedrag nog niet is voldaan, laat het ons weten, anders zien wij graag uw betaling tegemoet.'),(3,'controle administratie','Naar aanleiding van een controle binnen ons factureerprogramma is gebleken dat enkele oudere posten niet zijn afgeboekt. \r\nHet is mogelijk dat wij uw betaling niet juist verwerkt hebben, ook is het mogelijk dat uw betaling niet door ons ontvangen is. In dit laatste geval wil ik u vragen het openstaande bedrag per omgaande over te maken op ons bankrekeningnummer NL83RABO0318111128 t.n.v. Nieuwenhuizen Sprang-Capelle BV. \r\nIndien u de betreffende factuur wel betaald heeft, wil u dan zo vriendelijk zijn aan te geven wanneer en hoe de betaling heeft plaatsgevonden. \r\nWij rekenen erop dat u binnen 14 dagen een reactie kunt geven op dit verzoek. Wij danken u voor uw medewerking\r\nWij zien uw reactie graag zsm tegemoet.'),(4,'3e betalingsverzoek','Na de betalingsverzoeken welke wij u eerder toezonden, hebben wij nog steeds geen betaling van u mogen ontvangen. Hierbij verzoeken wij u het verschuldigde bedrag van bijgaande factuur per omgaande over te maken op ons bankrekeningnummer NL83RABO0318111128 t.n.v. Nieuwenhuizen Sprang-Capelle BV.\r\nIndien u niet aan dit verzoek voldoet, zijn wij genoodzaakt om de vordering uit handen te geven, waarbij alle bijkomende kosten voor uw rekening komen.\r\nMocht er een reden zijn waarom deze factuur nog niet is betaald, laat het ons weten, anders zien wij graag uw betaling tegemoet.');
/*!40000 ALTER TABLE `herinnering text` ENABLE KEYS */;
UNLOCK TABLES;

